select public.prepify_load_bank('Physics', 2, $j$[["If there are three points on basketball P1,P2 and P3 moves parallel to each other and there is no change in orientation which type of motion is this",["Translatory","Rotatory","Vibratory","Random"],"A",5,1,"5cc82e9182fa"],["An object is changing its position with respect to its surrounding which property explains this",["Heat","Light","Atomic","Mechanics"],"D",5,1,"b91eb69115c4"],["Study of motion without discussing the cause of motion is called",["Kinematics","Dynamics","Heat","Motion"],"A",5,1,"ad46c67c0ed0"],["The rest and motion of an object is explained by which property",["Absolute","Constant","Variable","Relative"],"D",5,1,"c2aed1d75b98"],["When an object repeat its motion about a point again and again this motion is known as",["Translatory","Rotatory","Vibratory","None of these"],"C",5,1,"29c53d356815"],["Which type of motion of earth causes day and night on earth",["Circular","Rotatory","Vibratory","Random"],"B",5,1,"939729193f06"],["If an object is moving from point A to B and take turn moves toward C it's total path is explained by",["Distance","Displacement","Speed","Velocity"],"A",5,1,"baea97e6f2b5"],["What is the name for this symbol '∆'",["Vector","Force","Delta","Rho"],"C",5,1,"14a0e823f0f9"],["If Sir Jamal running in an Olympics and the running track is oval shape what is his displacement",["Maximum","Minimum","Zero","Equal"],"C",5,1,"cd1470d2c675"],["Who is the fastest man on Earth",["Usain Bolt","Josh Inglis","Sangakkara","JP Duminy"],"A",5,1,"4008fe33a3f8"],["If a car is moving with a velocity of 70Km/hr neither speeding up nor slowing down which type of velocity is this",["Variable","Instantaneous","Uniform","Average"],"C",5,1,"1c3b760c2048"],["Which property has the fastest speed calculated on Earth",["Sound","Current","Light","Water"],"C",5,1,"6c40bde2a9cf"],["If you want to move with a speed of light which property should you remove",["Energy","Mass","Weight","Charge"],"B",5,1,"60f65305e31c"],["Who is the first scientist to measure the speed of any material is",["Einstein","Galileo","Newton","Hertz"],"B",5,1,"8e6fd9841184"],["If the distance time graph represent a parallel line along time Axis what information we get from this",["Uniform motion","Rest","Acceleration","Speed"],"B",5,1,"f7a35986c94d"],["If there is no a resistance a piece of paper and a coin is dropped from a top of building which would strike the earth first",["Paper","Coin","Dropper","Both at same time"],"D",5,1,"b6795e206d8c"],["If this speed and direction of moving body does not change with time then it's velocity is said to be",["Uniform","Contact","Variable","Zero"],"A",5,1,"5abe3f4ede45"],["If the direction of motion of a body and acceleration are in same direction then acceleration will be",["Uniform","Positive","Negative","Zero"],"B",5,1,"8fe93cf050ef"],["If a body is thrown upward then it's final velocity will be",["Uniform","Positive","Negative","Zero"],"D",5,1,"22959966ca87"],["If an object is dropped from top of building and is freely falling so the value of g depends on",["Mass","Speed","Size","Height"],"D",5,1,"a9417370c34a"],["A person A sitting in a bus says that he is at rest but an observer B standing on a road says that A is moving the right person is",["Person B","Person A","Both person","None of these"],"C",5,1,"982ed9d955c6"],["When an object is moving with uniform changing speed then the slope of speed time graph determine the magnitude of",["Displacement","Velocity","Acceleration","Momentum"],"C",5,1,"b08a656bf229"],["If an object is slowing down the acceleration will be",["Positive","Negative","Zero","Constant"],"B",5,1,"e956605f6462"],["At an amusement park, a ride swings back and forth but never leaves the same spot. What type of motion is this?",["Linear motion","Circular motion","Oscillatory motion","Random motion"],"C",5,1,"246cfac2dc12"],["A drone flies straight from the warehouse to drop a package 2km north, no turns. What type of motion is this?",["Rectilinear motion","Projectile motion","Rotational motion","Periodic motion"],"A",5,1,"a6ca7012bfc6"],["A batsman hits the ball and it follows a curved path before landing on the ground. What type of motion is this?",["Uniform motion","Circular motion","Projectile motion","Vibratory motion"],"C",5,1,"24c8c18a8b6a"],["Which type of motion is exhibited by a freely falling body?",["Circular Motion","Linear Motion","Rotatory Motion","Vibrational Motion"],"B",3,0,"e60ca4d75776"],["An athlete runs exactly one complete lap around a circular running track of radius R. What are the values of distance (s) and displacement (Δd) respectively?",["s = 0, Δd = 2πR","s = 2πR, Δd = 0","s = πR², Δd = 2R","s = 2R, Δd = 0"],"B",3,1,"464080c982ff"],["If a commuter travels 10 km due North, then makes a sharp right turn and drives 10 km due East, what is the total distance covered and the net displacement?",["Distance = 20 km, Displacement = 20 km","Distance = 14.14 km, Displacement = 20 km","Distance = 20 km, Displacement = 14.14 km North-East","Distance = 0 km, Displacement = 10 km"],"C",3,1,"4488a73703a9"],["A delivery truck travels along a winding track of length 1200 m in 60 seconds. The straight-line distance from its starting warehouse to its destination is 600 m. What is its average speed?",["10 m/s","20 m/s","30 m/s","5 m/s"],"B",3,0,"233843f8f4a5"],["An object is moving with a constant velocity of +15 m/s along a straight runway. What is its acceleration?",["+15 m/s²","-15 m/s²","Zero","Dependent on the total time elapsed"],"C",3,0,"8e16f5a6a026"],["A sports car accelerates uniformly from 10 m/s to 30 m/s over a time interval of 5 seconds. What is the precise rate of change of its velocity?",["8 m/s²","4 m/s²","6 m/s²","2 m/s²"],"B",3,0,"89851d5fe393"],["When an object is dropped in a true vacuum environment near Earth’s surface, its downward acceleration is:",["Dependent on the object’s total surface area profile","Directly proportional to the mass of the object","Constant at approximately 9.8 m/s², regardless of mass values","Progressively decreasing as the object gains velocity"],"C",3,1,"6d132cd92ce6"],["If a heavy iron ball and a light wooden ball are dropped simultaneously from the top of a tall tower in a vacuum chamber, which ball strikes the base first?",["The heavy iron ball hits significantly earlier","The light wooden ball hits significantly earlier","Both balls strike the base at the exact same instant","It depends heavily on which ball was released with more force"],"C",3,1,"710352835c8d"],["An object is dropped from rest from the edge of a high cliff. Assuming g = 10 m/s² for calculation ease, what will be its downward speed after exactly 3 seconds of free fall?",["15 m/s","30 m/s","45 m/s","9.8 m/s"],"B",3,1,"54d154502459"],["The study of motion without considering the forces involved is called:",["Dynamics","Statics","Kinematics","Thermodynamics"],"C",3,0,"70ddc1ed8e1b"],["What is an example of rotatory motion?",["A car moving on a road","A wheel spinning about its axle","A ball falling from a height","A person walking"],"B",3,0,"0b7c093e2ed3"],["If a car is traveling westward along a straight highway and applies its brakes to slow down, what are the directions of its velocity and acceleration vectors respectively?",["Velocity is West, Acceleration is West","Velocity is East, Acceleration is West","Velocity is West, Acceleration is East","Both vectors drop instantly to zero"],"C",3,1,"7a5f5ae8bc01"],["Which of the following is the correct formula for speed?",["Speed = Time / Distance","Speed = Distance x Time","Speed = Distance / Time","Speed = Time x Acceleration"],"C",3,0,"9954b8e72338"],["When does an object accelerate?",["Only when its speed increases","Only when its speed decreases","Only when its direction of motion changes","When there is a change in its speed, direction, or both"],"D",3,0,"cf856d7284b2"],["If a car is traveling around a circular track at a constant speed of 50 km/h, is it accelerating?",["Yes, because its direction is constantly changing","No, because the speed is constant","No, because the velocity is constant","Yes, because the distance is increasing"],"A",3,1,"cc487bf738dc"],["What is the SI unit of acceleration?",["m/s","m/s²","m/s³","kg/m³"],"B",3,0,"a9845a4ab5d3"],["The area under a speed–time graph represents:",["Speed","Volume","Acceleration","Distance"],"D",3,0,"9cb3cbdc7823"],["A particle starts from rest and achieves a velocity of 24 m/s in a span of 6 seconds along a linear track. What is its average acceleration?",["4 m/s²","144 m/s²","2 m/s²","0.25 m/s²"],"A",3,0,"e748cecc7f5f"],["If a body covers equal distance in equal intervals of time, then the speed of the body is known as:",["Uniform","Variable","Non uniform","All of these"],"A",3,1,"9a37eab3cb2a"],["If a satellite is moving in a circle with constant speed, its velocity will be:",["Uniform","Constant","Variable","All of these"],"C",3,1,"5060f9795193"],["If the velocity of the body is decreasing then its acceleration will be:",["Positive","Negative","Zero","Uniform"],"B",3,0,"601c7fd40759"],["If the velocity of the body is increasing then its acceleration will be:",["Positive","Negative","Zero","Non-uniform"],"A",3,0,"520842ade0c6"],["If the velocity of a body is uniform then its acceleration will be:",["Positive","Negative","Zero","Doubled"],"C",3,0,"46ae50438941"],["A passenger train traveling eastward along a straight track begins to slow down as it approaches a station. The direction of the train's acceleration is:",["Toward the East","Toward the West","Vertically downward","It has no direction because it is slowing down"],"B",3,0,"4510b4a8f258"],["An airplane is flying toward the Southeast when the pilot throttles back the engines, causing the plane to slow down. The direction of the aircraft's acceleration is toward the:",["Southeast","Northwest","Southwest","Northeast"],"B",3,0,"33a7c6a5ada3"],["A driver presses the gas pedal of a car moving along a straight highway, causing it to speed up in the forward direction. In this situation, the car's acceleration is:",["Negative","Positive","Zero","Non-uniform"],"B",3,1,"8a3bbe81feaf"],["A speed-time graph features a straight line sloping downward toward the right. This represents:",["Uniform acceleration","Uniform deceleration","Non-uniform acceleration","Constant speed"],"B",3,0,"a294ddb3eb3c"],["When a distance-time graph shows a curved line that bends gradually upward (getting steeper), the motion of the body can be described as:",["Uniform speed","Constant velocity","Non-uniform speed where the object is speeding up","Non-uniform speed where the object is slowing down"],"C",3,0,"32576a985761"],["The slope (or gradient) of a distance-time graph directly represents which physical quantity?",["Displacement","Acceleration","Distance","Speed"],"D",3,0,"87b98fb9cdd1"],["If the distance-time graph of a moving object is a perfectly flat, horizontal line parallel to the time axis, it indicates that:",["The object is moving with constant speed","The object is at complete rest","The object is moving with uniform acceleration","The object is returning back to its starting point"],"B",3,0,"1ff11d87b15f"],["An object is thrown vertically straight upward into the air. At the highest point of its flight, the object’s velocity and acceleration are:",["Velocity is zero, and acceleration is zero","Velocity is zero, and acceleration is equal to acceleration due to gravity","Velocity is maximum, and acceleration is zero","Velocity is maximum, and acceleration is equal to acceleration due to gravity"],"B",3,0,"5a670fa7f80f"],["The gradient (slope) of speed time curve gives magnitude of:",["Distance","Speed","Time","Acceleration"],"D",3,0,"d7d864e9d686"],["The speedometer of a car shows:",["Average speed","Instantaneous speed","Uniform acceleration","Total distance"],"B",3,0,"5a9343081594"],["The motion of a guitar string when plucked is an example of:",["Linear motion","Circular motion","Vibratory motion","Random motion"],"C",3,0,"539b644b96c2"],["A car moving north applies its brakes and slows down. The directions of its velocity and acceleration are:",["north and north","north and south","south and north","south and south"],"B",5,0,"7a5f5ae8bc01"],["A football kicked into the air follows a curved path before landing. This is:",["circular motion","projectile motion","rotatory motion","vibratory motion"],"B",1,1,"24c8c18a8b6a"],["The pendulum of a wall clock moving to and fro about its mean position is an example of:",["translatory motion","rotatory motion","vibratory motion","random motion"],"C",1,0,"29c53d356815"],["A lift moving straight up its shaft without turning shows:",["rectilinear (translatory) motion","projectile motion","rotatory motion","vibratory motion"],"A",3,1,"a6ca7012bfc6"],["A car that is speeding up in the direction of its motion has an acceleration that is:",["positive","negative","zero","undefined"],"A",3,0,"e956605f6462"],["A ball thrown vertically upward is momentarily at rest at the top. Its velocity at that point is:",["maximum","zero","equal to g","negative 10 m/s"],"B",3,0,"22959966ca87"],["The total length of the path travelled by a body, whatever its direction, is called:",["displacement","distance","velocity","acceleration"],"B",1,0,"baea97e6f2b5"],["A cyclist rides along a winding road 220 m long in 20 s. The straight-line distance from start to finish is 132 m. The cyclist's average speed is:",["17.6 m/s","11 m/s","22 m/s","6.6 m/s"],"B",3,0,"233843f8f4a5"],["A cyclist rides along a winding road 840 m long in 60 s. The straight-line distance from start to finish is 420 m. The cyclist's average speed is:",["28 m/s","21 m/s","14 m/s","7 m/s"],"C",3,0,"233843f8f4a5"],["A train covers 100 km in 2 hours. Its average speed is:",["100 km/h","200 km/h","25 km/h","50 km/h"],"D",3,0,"233843f8f4a5"],["A cyclist rides along a winding road 400 m long in 50 s. The straight-line distance from start to finish is 240 m. The cyclist's average speed is:",["4.8 m/s","16 m/s","8 m/s","12.8 m/s"],"C",3,0,"233843f8f4a5"],["A train covers 120 km in 2 hours. Its average speed is:",["60 km/h","120 km/h","30 km/h","240 km/h"],"A",3,0,"233843f8f4a5"],["A bus covers 250 km in 5 hours. Its average speed is:",["100 km/h","50 km/h","1250 km/h","25 km/h"],"B",3,0,"233843f8f4a5"],["A train speeds up uniformly from 15 m/s to 25 m/s in 2 s. Its acceleration is:",["20 m/s²","5 m/s²","12.5 m/s²","6 m/s²"],"B",3,0,"89851d5fe393"],["A car speeds up uniformly from 15 m/s to 27 m/s in 3 s. Its acceleration is:",["4 m/s²","36 m/s²","9 m/s²","14 m/s²"],"A",3,0,"89851d5fe393"],["A train speeds up uniformly from 20 m/s to 32 m/s in 2 s. Its acceleration is:",["24 m/s²","16 m/s²","26 m/s²","6 m/s²"],"D",3,0,"89851d5fe393"],["A bus speeds up uniformly from 5 m/s to 25 m/s in 4 s. Its acceleration is:",["7.5 m/s²","5 m/s²","80 m/s²","6.25 m/s²"],"B",3,0,"89851d5fe393"],["A car speeds up uniformly from 20 m/s to 32 m/s in 4 s. Its acceleration is:",["3 m/s²","48 m/s²","8 m/s²","13 m/s²"],"A",3,0,"89851d5fe393"],["A motorcycle speeds up uniformly from 10 m/s to 34 m/s in 8 s. Its acceleration is:",["192 m/s²","3 m/s²","4.25 m/s²","5.5 m/s²"],"B",3,0,"89851d5fe393"],["A particle starts from rest and reaches a velocity of 18 m/s in 9 s. Its average acceleration is:",["2 m/s²","162 m/s²","1 m/s²","0.5 m/s²"],"A",3,0,"e748cecc7f5f"],["A particle starts from rest and reaches a velocity of 9 m/s in 3 s. Its average acceleration is:",["1.5 m/s²","27 m/s²","3 m/s²","0.33 m/s²"],"C",3,0,"e748cecc7f5f"],["A particle starts from rest and reaches a velocity of 24 m/s in 8 s. Its average acceleration is:",["192 m/s²","1.5 m/s²","0.33 m/s²","3 m/s²"],"D",3,0,"e748cecc7f5f"],["A particle starts from rest and reaches a velocity of 36 m/s in 6 s. Its average acceleration is:",["6 m/s²","216 m/s²","0.17 m/s²","3 m/s²"],"A",3,0,"e748cecc7f5f"],["A particle starts from rest and reaches a velocity of 42 m/s in 7 s. Its average acceleration is:",["6 m/s²","294 m/s²","0.17 m/s²","3 m/s²"],"A",3,0,"e748cecc7f5f"],["A particle starts from rest and reaches a velocity of 40 m/s in 8 s. Its average acceleration is:",["2.5 m/s²","0.2 m/s²","320 m/s²","5 m/s²"],"D",3,0,"e748cecc7f5f"],["A car moving at 12 m/s is brought to rest by its brakes in 4 s. Its acceleration is:",["0 m/s²","−3 m/s²","−48 m/s²","3 m/s²"],"B",3,1,"gen-physics-p2-deceleration"],["A car moving at 30 m/s is brought to rest by its brakes in 6 s. Its acceleration is:",["−5 m/s²","−180 m/s²","0 m/s²","5 m/s²"],"A",3,1,"gen-physics-p2-deceleration"],["A car moving at 12 m/s is brought to rest by its brakes in 2 s. Its acceleration is:",["−6 m/s²","6 m/s²","0 m/s²","−24 m/s²"],"A",3,1,"gen-physics-p2-deceleration"],["A car moving at 24 m/s is brought to rest by its brakes in 6 s. Its acceleration is:",["0 m/s²","−4 m/s²","4 m/s²","−144 m/s²"],"B",3,1,"gen-physics-p2-deceleration"],["A car moving at 18 m/s is brought to rest by its brakes in 3 s. Its acceleration is:",["0 m/s²","6 m/s²","−54 m/s²","−6 m/s²"],"D",3,1,"gen-physics-p2-deceleration"],["A car moving at 15 m/s is brought to rest by its brakes in 3 s. Its acceleration is:",["−5 m/s²","−45 m/s²","0 m/s²","5 m/s²"],"A",3,1,"gen-physics-p2-deceleration"],["A stone is dropped from rest from the top of a tall building. Taking g = 10 m/s², its speed after 5 s is:",["15 m/s","125 m/s","2 m/s","50 m/s"],"D",3,0,"54d154502459"],["A stone is dropped from rest from the top of a tall building. Taking g = 10 m/s², its speed after 1 s is:",["5 m/s","20 m/s","10 m/s","11 m/s"],"C",3,0,"54d154502459"],["A stone is dropped from rest from the top of a tall building. Taking g = 10 m/s², its speed after 4 s is:",["80 m/s","2.5 m/s","14 m/s","40 m/s"],"D",3,0,"54d154502459"],["A stone is dropped from rest from the top of a tall building. Taking g = 10 m/s², its speed after 6 s is:",["180 m/s","1.67 m/s","16 m/s","60 m/s"],"D",3,0,"54d154502459"],["A stone is dropped from rest from the top of a tall building. Taking g = 10 m/s², its speed after 2 s is:",["40 m/s","5 m/s","20 m/s","12 m/s"],"C",3,0,"54d154502459"],["A stone dropped from rest falls freely for 5 s. Taking g = 10 m/s², the distance it falls is:",["25 m","125 m","250 m","50 m"],"B",5,0,"gen-physics-p2-free-fall-distance"],["A stone dropped from rest falls freely for 2 s. Taking g = 10 m/s², the distance it falls is:",["40 m","10 m","20 m","80 m"],"C",5,0,"gen-physics-p2-free-fall-distance"],["A stone dropped from rest falls freely for 4 s. Taking g = 10 m/s², the distance it falls is:",["20 m","40 m","80 m","160 m"],"C",5,0,"gen-physics-p2-free-fall-distance"],["A stone dropped from rest falls freely for 3 s. Taking g = 10 m/s², the distance it falls is:",["90 m","30 m","45 m","15 m"],"C",5,0,"gen-physics-p2-free-fall-distance"],["A trolley moving at 9 m/s accelerates uniformly at 5 m/s² for 2 s. Its final velocity is:",["10 m/s","90 m/s","28 m/s","19 m/s"],"D",3,0,"gen-physics-p2-final-velocity"],["A trolley moving at 5 m/s accelerates uniformly at 4 m/s² for 5 s. Its final velocity is:",["100 m/s","45 m/s","25 m/s","20 m/s"],"C",3,0,"gen-physics-p2-final-velocity"],["A trolley moving at 10 m/s accelerates uniformly at 2 m/s² for 7 s. Its final velocity is:",["84 m/s","14 m/s","140 m/s","24 m/s"],"D",3,0,"gen-physics-p2-final-velocity"],["A boat moving at 11 m/s accelerates uniformly at 3 m/s² for 7 s. Its final velocity is:",["98 m/s","21 m/s","32 m/s","231 m/s"],"C",3,0,"gen-physics-p2-final-velocity"],["A cyclist moving at 8 m/s accelerates uniformly at 4 m/s² for 6 s. Its final velocity is:",["32 m/s","72 m/s","192 m/s","24 m/s"],"A",3,0,"gen-physics-p2-final-velocity"],["A boat moving at 4 m/s accelerates uniformly at 2 m/s² for 8 s. Its final velocity is:",["20 m/s","64 m/s","48 m/s","16 m/s"],"A",3,0,"gen-physics-p2-final-velocity"],["A car starts from rest and accelerates uniformly at 2 m/s² for 7 s. The distance it covers is:",["49 m","14 m","98 m","7 m"],"A",5,0,"gen-physics-p2-distance-from-rest"],["A car starts from rest and accelerat